   229	bool SoftimagePICHandler::canRead() const
   230	{
   231	    if (!SoftimagePICHandler::canRead(device())) {
   232	        return false;
   233	    }
   234	    setFormat("pic");
   235	    return true;
   236	}
   237	
   238	bool SoftimagePICHandler::read(QImage *image)
   239	{
   240	    if (!readChannels()) {
   241	        return false;
   242	    }
   243	
   244	    QImage::Format fmt = QImage::Format_RGB32;
   245	    for (const PicChannel &channel : qAsConst(m_channels)) {
   246	        if (channel.size != 8) {
   247	            // we cannot read images that do not come in bytes
   248	            qDebug() << "Channel size was" << channel.size;
   249	            m_state = Error;
   250	            return false;
   251	        }
   252	        if (channel.code & ALPHA) {
   253	            fmt = QImage::Format_ARGB32;
   254	        }
   255	    }
   256	
   257	    QImage img(m_header.width, m_header.height, fmt);
   258	    img.fill(qRgb(0,0,0));
   259	
   260	    for (int y = 0; y < m_header.height; y++) {
   261	        QRgb *row = reinterpret_cast<QRgb*>(img.scanLine(y));
   262	        if (!readRow(m_dataStream, row, m_header.width, m_channels)) {
   263	            qDebug() << "readRow failed";
   264	            m_state = Error;
   265	            return false;
   266	        }
   267	    }
   268	
   269	    *image = img;
   270	    m_state = Ready;
   271	
   272	    return true;
   273	}
   274	
   275	bool SoftimagePICHandler::write(const QImage &_image)
   276	{
   277	    bool alpha = _image.hasAlphaChannel();
   278	    const QImage image = _image.convertToFormat(
   279	            alpha ? QImage::Format_ARGB32
   280	                  : QImage::Format_RGB32);
   281	
   282	    if (image.width() < 0 || image.height() < 0) {
   283	        qDebug() << "Image size invalid:" << image.width() << image.height();
   284	        return false;
   285	    }
   286	    if (image.width() > 65535 || image.height() > 65535) {
   287	        qDebug() << "Image too big:" << image.width() << image.height();
   288	        // there are only two bytes for each dimension
   289	        return false;
   290	    }
   291	
   292	    QDataStream stream(device());
   293	
   294	    stream << PicHeader(image.width(), image.height(), m_description);
   295	
   296	    PicChannelEncoding encoding = m_compression ? MixedRLE : Uncompressed;
   297	    QList<PicChannel> channels;
   298	    channels << PicChannel(encoding, RED | GREEN | BLUE);
   299	    if (alpha) {
   300	        channels << PicChannel(encoding, ALPHA);
   301	    }
   302	    stream << channels;
   303	
   304	    for (int r = 0; r < image.height(); r++) {
   305	        const QRgb *row = reinterpret_cast<const QRgb*>(image.scanLine(r));
   306	
   307	        /* Write the RGB part of the scanline */
   308	        auto rgbEqual = [] (QRgb p1, QRgb p2) -> bool {
   309	            return qRed(p1) == qRed(p2) &&
   310	                   qGreen(p1) == qGreen(p2) &&
   311	                   qBlue(p1) == qBlue(p2);
   312	        };
   313	        auto writeRgb = [] (QDataStream &str, QRgb pixel) -> void {
   314	            str << quint8(qRed(pixel))
   315	                << quint8(qGreen(pixel))
   316	                << quint8(qBlue(pixel));
   317	        };
   318	        if (m_compression) {
   319	            encodeRLEData(RLEVariant::PIC, stream, row, image.width(),
   320	                          rgbEqual, writeRgb);
   321	        } else {
   322	            for (int i = 0; i < image.width(); ++i) {
   323	                writeRgb(stream, row[i]);
   324	            }
   325	        }
   326	
   327	        /* Write the alpha channel */
   328	        if (alpha) {
   329	            auto alphaEqual = [] (QRgb p1, QRgb p2) -> bool {
   330	                return qAlpha(p1) == qAlpha(p2);
   331	            };
   332	            auto writeAlpha = [] (QDataStream &str, QRgb pixel) -> void {
   333	                str << quint8(qAlpha(pixel));
   334	            };
   335	            if (m_compression) {
   336	                encodeRLEData(RLEVariant::PIC, stream, row, image.width(),
   337	                              alphaEqual, writeAlpha);
   338	            } else {
   339	                for (int i = 0; i < image.width(); ++i) {
   340	                    writeAlpha(stream, row[i]);
   341	                }
   342	            }
   343	        }
   344	    }
   345	    return stream.status() == QDataStream::Ok;
   346	}
   347	
   348	bool SoftimagePICHandler::canRead(QIODevice *device)
   349	{
   350	    char data[4];
   351	    if (device->peek(data, 4) != 4) {
   352	        return false;
   353	    }
   354	    return qFromBigEndian<qint32>(reinterpret_cast<uchar*>(data)) == PIC_MAGIC_NUMBER;
   355	}
   356	
   357	bool SoftimagePICHandler::readHeader()
   358	{
   359	    if (m_state == Ready) {
   360	        m_state = Error;
   361	        m_dataStream.setDevice(device());
   362	        m_dataStream >> m_header;
   363	        if (m_header.isValid() && m_dataStream.status() == QDataStream::Ok) {
   364	            m_state = ReadHeader;
   365	        }
   366	    }
   367	    return m_state != Error;
   368	}
   369	
   370	bool SoftimagePICHandler::readChannels()
   371	{
   372	    readHeader();
   373	    if (m_state == ReadHeader) {
   374	        m_state = Error;
   375	        m_dataStream >> m_channels;
   376	        if (m_dataStream.status() == QDataStream::Ok) {
   377	            m_state = ReadChannels;
   378	        }
   379	    }
   380	    return m_state != Error;
   381	}
   382	
   383	void SoftimagePICHandler::setOption(ImageOption option, const QVariant &value)
   384	{
   385	    switch (option) {
   386	        case CompressionRatio:
   387	            m_compression = value.toBool();
   388	            break;
   389	        case Description: {
   390	            m_description.clear();
   391	            const QStringList entries = value.toString().split(QStringLiteral("\n\n"));
   392	            for (const QString &entry : entries) {
   393	                if (entry.startsWith(QStringLiteral("Description: "))) {
   394	                    m_description = entry.mid(13).simplified().toUtf8();
   395	                }
   396	            }
   397	            break;
   398	        }
   399	        default:
   400	            break;
   401	    }
   402	}
   403	
   404	QVariant SoftimagePICHandler::option(ImageOption option) const
   405	{
   406	    const_cast<SoftimagePICHandler*>(this)->readHeader();
   407	    switch (option) {
   408	        case Size:
   409	            if (const_cast<SoftimagePICHandler*>(this)->readHeader()) {
   410	                return QSize(m_header.width, m_header.height);
   411	            } else {
   412	                return QVariant();
   413	            }
   414	        case CompressionRatio:
   415	            return m_compression;
   416	        case Description:
   417	            if (const_cast<SoftimagePICHandler*>(this)->readHeader()) {
   418	                QString descStr = QString::fromUtf8(m_header.comment);
   419	                if (!descStr.isEmpty()) {
   420	                    return QString(QStringLiteral("Description: ") +
   421	                           descStr +
   422	                           QStringLiteral("\n\n"));
   423	                }
   424	            }
   425	            return QString();
   426	        case ImageFormat:
   427	            if (const_cast<SoftimagePICHandler*>(this)->readChannels()) {
   428	                for (const PicChannel &channel : qAsConst(m_channels)) {
   429	                    if (channel.code & ALPHA) {
   430	                        return QImage::Format_ARGB32;
   431	                    }
   432	                }
   433	                return QImage::Format_RGB32;
   434	            }
   435	            return QVariant();
   436	        default:
   437	            return QVariant();
   438	    }
   439	}
   440	
   441	bool SoftimagePICHandler::supportsOption(ImageOption option) const
   442	{
   443	    return (option == CompressionRatio ||
   444	            option == Description ||
   445	            option == ImageFormat ||
   446	            option == Size);
   447	}
   448	
   449	QImageIOPlugin::Capabilities SoftimagePICPlugin::capabilities(QIODevice *device, const QByteArray &format) const
   450	{
   451	    if (format == "pic") {
   452	        return Capabilities(CanRead | CanWrite);
   453	    }
   454	    if (!format.isEmpty()) {
   455	        return {};
   456	    }
   457	    if (!device->isOpen()) {
   458	        return {};
   459	    }
   460	
   461	    Capabilities cap;
   462	    if (device->isReadable() && SoftimagePICHandler::canRead(device)) {
   463	        cap |= CanRead;
   464	    }
   465	    if (device->isWritable()) {
   466	        cap |= CanWrite;
   467	    }
   468	    return cap;
   469	}
   470	
   471	QImageIOHandler *SoftimagePICPlugin::create(QIODevice *device, const QByteArray &format) const
   472	{
   473	    QImageIOHandler *handler = new SoftimagePICHandler();
   474	    handler->setDevice(device);
   475	    handler->setFormat(format);
   476	    return handler;
   477	}
