   102	static bool LoadRAS(QDataStream &s, const RasHeader &ras, QImage &img)
   103	{
   104	    s.device()->seek(RasHeader::SIZE);
   105	
   106	    // QVector uses some extra space for stuff, hence the 32 here suggested by thiago
   107	    if (ras.ColorMapLength > std::numeric_limits<int>::max() - 32) {
   108	        qWarning() << "LoadRAS() unsupported image color map length in file header" << ras.ColorMapLength;
   109	        return false;
   110	    }
   111	
   112	    // Read palette if needed.
   113	    QVector<quint8> palette(ras.ColorMapLength);
   114	    if (ras.ColorMapType == 1) {
   115	        for (quint32 i = 0; i < ras.ColorMapLength; ++i) {
   116	            s >> palette[i];
   117	        }
   118	    }
   119	
   120	    const int bpp = ras.Depth / 8;
   121	    if (ras.Height == 0) {
   122	        return false;
   123	    }
   124	    if (bpp == 0) {
   125	        return false;
   126	    }
   127	    if (ras.Length / ras.Height / bpp < ras.Width) {
   128	        qWarning() << "LoadRAS() mistmatch between height and width" << ras.Width << ras.Height << ras.Length << ras.Depth;
   129	        return false;
   130	    }
   131	    // QVector uses some extra space for stuff, hence the 32 here suggested by thiago
   132	    if (ras.Length > std::numeric_limits<int>::max() - 32) {
   133	        qWarning() << "LoadRAS() unsupported image length in file header" << ras.Length;
   134	        return false;
   135	    }
